const S = 182.78964407016804
export function pt(lon: number, lat: number): [number, number] {
    let l = lon - 10
    if (l < -180) l += 360
    if (l > 180) l -= 360
    const la = (l * Math.PI) / 180, p = (lat * Math.PI) / 180, p2 = p * p, p4 = p2 * p2
    const x = la * (0.8707 - 0.131979 * p2 + p4 * (-0.013791 + p4 * (0.003971 * p2 - 0.001529 * p4)))
    const y = p * (1.007226 + p2 * (0.015085 + p4 * (-0.044475 + 0.028874 * p2 - 0.005916 * p4)))
    return [500 + S * x, 259.998 - S * y]
}

